import { Component } from '@angular/core';
import { Config, ModalController, NavParams } from '@ionic/angular';

import { ConferenceData } from '../../providers/conference-data';
import { FirestoreService } from 'src/app/providers/firestore.service';


@Component({
  selector: 'page-schedule-filter',
  templateUrl: 'schedule-filter.html',
  styleUrls: ['./schedule-filter.scss'],
})
export class ScheduleFilterPage {
  ios: boolean;
  loading: boolean = true;
  tracks: {name: string,  isChecked: boolean}[];

  constructor(
    public confData: ConferenceData,
    private config: Config,
    public modalCtrl: ModalController,
    public navParams: NavParams,
    private api: FirestoreService
  ) { 
    this.tracks = [{
      name:'Net Benefit',
      isChecked: true,
     },
     {
       name:'A-Z',
       isChecked: false
      }
  ]
}

  async ionViewWillEnter() {
    
    let activeFilter = await this.api.getTreatmentFilter();
    if (activeFilter !== null) {
    
      this.tracks.forEach((item)=> {
        if(item.name === activeFilter) {
          item.isChecked = true
        }
        else {
          item.isChecked = false;
        }
      })
    }
    this.loading = false;
    this.ios = this.config.get('mode') === `ios`;

    // passed in array of track names that should be excluded (unchecked)
    // const excludedTrackNames = this.navParams.get('excludedTracks');

    

  }

  selectAll(check: boolean) {
    // set all to checked or unchecked
    this.tracks.forEach(track => {
      track.isChecked = check;
    });
  }

  onTrackClick(track:any) {
    this.tracks.forEach((item=> {
      if(track.name !== item.name ) {
        item.isChecked = false;
 
      }
    }))
    this.api.setTreatmentFilter(track.name);
  }

  applyFilters() {
    // Pass back a new array of track names to exclude
    const excludedTrackNames = this.tracks.filter(c => c.isChecked).map(c => c.name);
    this.dismiss(excludedTrackNames);
  }

  dismiss(data?: any) {
    // using the injected ModalController this page
    // can "dismiss" itself and pass back data
    this.modalCtrl.dismiss(data);
  }
}
