import { Component } from "@angular/core";
import { ConferenceData } from "../../providers/conference-data";

@Component({
  selector: "page-speaker-list",
  templateUrl: "speaker-list.html",
  styleUrls: ["./speaker-list.scss"],
})
export class SpeakerListPage {
  homelinks = [
    {
      name: "Treatment Ratings",
      description:
        "View Treatment Ratings. Each treatment is rated as to Overall Benefit (0-4) and Adverse Effect (0-3)",
      image:
        "assets/img/wizard-2.png",
      route: "app/tabs/schedule",
    },
    {
      name: "Symptom Search",
      description: "Find the top treatments for different symptoms here, based on the % of families who reported the treatment improved that symptom",
      image:
      "assets/img/wizard-3.png",
      route: "app/tabs/symptoms",
    },
    {
      name: "ANRC Guidelines",
      description:
        "Read about the nutritional guidelines from the Autism Nutrition Research Center",
      image:
      "assets/img/guidelines.png",
      route: "/app/tabs/guide",
    },
   
    {
      name: "About us",
      description: "For reading more about ANRC tap here",
      image:
        "/assets/img/aboutus.png",
      route: "/app/tabs/about",
    }
    // {
    //   name: "Symptom Questionnaires",
    //   description: "Coming Soon: Find some different autism symptom assessments here",
    //   image:
    //     "https://images.unsplash.com/photo-1489710437720-ebb67ec84dd2?ixid=MXwxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHw%3D&ixlib=rb-1.2.1&auto=format&fit=crop&w=1650&q=80",
    //   route: "",
    // },
  ];
  speakers: any[] = [];

  constructor(public confData: ConferenceData) {}

  ionViewDidEnter() {
    this.confData.getSpeakers().subscribe((speakers: any[]) => {
      this.speakers = speakers;
    });
  }
}
