import { Component, ViewChild, ElementRef } from "@angular/core";

import { ConferenceData } from "../../providers/conference-data";
import { ActivatedRoute, Router } from "@angular/router";
import { UserData } from "../../providers/user-data";
import * as Highcharts from "highcharts";
import { ITreatment } from "../../providers/treatments.model";

import {
  BarChartConfig,
  AdverseChartConfig,
  SymptomsChartConfig,
} from "./chart.config";
import { NavParams, ModalController, IonRouterOutlet, NavController } from "@ionic/angular";
import { IsDefined } from "../../utils/helpers";
import { FirestoreService } from "../../providers/firestore.service";
import { TreatmentInfoComponent } from "../../components/treatment-info/treatment-info.component";
import { IfStmt } from '@angular/compiler';

@Component({
  selector: "page-session-detail",
  styleUrls: ["./session-detail.scss"],
  templateUrl: "session-detail.html",
})
export class SessionDetailPage {
  treatment: ITreatment;
  isFavorite = false;
  defaultHref = "";
  Highcharts: typeof Highcharts = Highcharts;
  chartOptions: Highcharts.Options;
  showChart: boolean = false;
  height: number;
  isChartReady: boolean;
  symptomBenefitChartConfig: any = SymptomsChartConfig;
  adverseSymptomBenefitChartConfig: any = AdverseChartConfig;
  benefitVsAdverseChartConfig: any = BarChartConfig;
  rating: number;

  nographdata = false;
  heightSection4:number; 
  @ViewChild("chart")
  chart: ElementRef<HTMLDivElement>;
  ratingDisplay: string;
  ratingCSS: string;
  @ViewChild("wrapper", { read: ElementRef }) private wrapper: ElementRef;
  @ViewChild("section3", { read: ElementRef }) private section3: ElementRef;
  @ViewChild("section4", { read: ElementRef }) private section4: ElementRef;
  wrapperHeight: any = 0;
  wrapperStyle: any = '';
  width: any;
  backUrl: string = null;
  section3HeightChart:any;
  section4HeightChart:any;
  loading: boolean = false;
  showWarning: boolean = true;
  warningMsg: string = '';
  constructor(
    private dataProvider: ConferenceData,
    private userProvider: UserData,
    private route: ActivatedRoute,
    private params: NavParams,
    private router: Router,
    private api: FirestoreService,
    public routerOutlet: IonRouterOutlet,
    public modal: ModalController,
    public nav: NavController
  ) {
   
    let _navPram = this.router.getCurrentNavigation().extras
    
    if(_navPram.state && _navPram.state.treatment && _navPram.state.treatment.hasOwnProperty('overallBenefit')) {
      this.treatment = _navPram.state['treatment'] as ITreatment;
      this.showWarning = (this.treatment.name.toLowerCase().indexOf('anrc') !== -1) ? true : false;
      if(_navPram.state.hasOwnProperty('from')) {
        this.backUrl =  _navPram.state['from']
       
      }
      else {
        this.defaultHref = `/app/tabs/schedule`;
      }
      this.loading = false;
    }
    else {
      this.defaultHref = `/app/tabs/schedule`;
  
     this._loadTreatment();
    }
  }

 
  goBack() {
    if(this.backUrl !== null) {
      this.nav.navigateBack(this.backUrl);
    }
    else {
      this.nav.back();
    }
  }

  async ionViewDidEnter() {
   
    
   
    this.wrapperHeight = 0;
    this.section3HeightChart = 50;
    this.section4HeightChart = 50;
   
    if(!this.treatment) {
      this._loadTreatment();
    }
    else {
    
      this.load();
    }
    
   
  }

  load() {
    this.width = this.wrapper.nativeElement.offsetWidth ;
    this.height = this.section3.nativeElement.offsetHeight;
    this.heightSection4 = this.section4.nativeElement.offsetHeight;
    this.calculateRating();
    this.calculateRatingDisplay();
    this.loadCharts();
  }

  formatDisplay() {
    return this.ratingDisplay === "very-good" ? "very good" : this.ratingDisplay;
  }

  formatSubCategory(name) {
    if(name.toLowerCase().indexOf('chelation') != -1) {
        return "Chelation/Detoxification";
    }
    else {
        return name;
    }
}

  calculateRatingDisplay() {
    if (this.rating < 0) {
      this.rating = 0;
    }
    if(this.rating > 5) {
      this.rating = 5;
    }
    if (this.rating < 0 || (this.rating >= 0 && this.rating <= 1)) {
      this.ratingDisplay = "Poor";

      this.ratingCSS = this.ratingDisplay.toLowerCase();
    } else if (this.rating > 1 && this.rating <= 2) {
      this.ratingDisplay = "Fair";
      this.ratingCSS = this.ratingDisplay.toLowerCase();
    } else if (this.rating > 2 && this.rating <= 3) {
      this.ratingDisplay = "Good";
      this.ratingCSS = this.ratingDisplay.toLowerCase();
    } else if (this.rating > 3 && this.rating <= 4) {
      this.ratingDisplay = "Very Good";
      this.ratingCSS = "very-good";
    } else if (this.rating > 4 && this.rating <= 5) {
      this.ratingDisplay = "Excellent";
      this.ratingCSS = this.ratingDisplay.toLowerCase();
    }
  }

  calculateRating() {

    let _benefitVal = (IsDefined(this.treatment.overallBenefit) && this.treatment.overallBenefit.value >= 0 ) ? this.treatment.overallBenefit.value : 0;
    let _adverseVal = (IsDefined(this.treatment.overallAdverse) && this.treatment.overallAdverse.value >= 0 ) ? this.treatment.overallAdverse.value : 0;
    
      this.rating = Number(
        (
          (_benefitVal -
            _adverseVal) *
          2
        ).toFixed(1)
      );
    
      if(this.rating === NaN || this.rating === undefined || this.rating < 0 ) {
        this.rating = 0;
      }
  }

  loadCharts() {
    this._configureBenefitVsAdveseChart();
    this._configureSymptomBenefitChart();
    this._configureSymptomAdverseChart();
    this.isChartReady = true;

  }

  async showInfo(section: string) {
    const modal = await this.modal.create({
      component: TreatmentInfoComponent,
      swipeToClose: true,
      presentingElement: this.routerOutlet.nativeEl,
      componentProps: { section: section },
    });
    await modal.present();
  }

  private async _loadTreatment() {
 
    if(!this.loading) {
      let _urlPaths = this.router.routerState.snapshot.url.split('/');
      let _treatmentName = _urlPaths[_urlPaths.length - 1];
      this.loading = true;
      
      _treatmentName = _treatmentName
        .replace("-s-", " ")
        .replace("-f-", "/")
        .replace("-sf-", "(")
        .replace('-c-', ",")
        .replace('-p-', "|")
        .replace("-sb-", ")");

      this.treatment = await this.api.getTreatment(_treatmentName)
      this.showWarning = (this.treatment.name.toLowerCase().indexOf('anrc') !== -1) ? true : false;
      this.loading = false;
      this.load();
    }
  }

  private _configureBenefitVsAdveseChart() {
    // temp hack, this is nasty. so much can go wrong here
    this.benefitVsAdverseChartConfig.title.text = undefined;
    this.benefitVsAdverseChartConfig.chart.width = this.width ;
    this.benefitVsAdverseChartConfig.series[0]["data"][0].y = IsDefined(
      this.treatment.overallBenefit.value
    )
      ? this.treatment.overallBenefit.value
      : 0;
    this.benefitVsAdverseChartConfig.series[0]["data"][1].y = IsDefined(
      this.treatment.overallAdverse.value
    )
      ? this.treatment.overallAdverse.value
      : 0;
  }

  private _configureSymptomBenefitChart() {
    let _data = [];
    let _labels = [];

    for (const [key, value] of Object.entries(this.treatment.symptomBenefits)) {
      if(key.toLowerCase().indexOf('other') === -1) {
        let _val = Number(value).toFixed(0)  
      
        _labels.push(_val+ " %");
        _data.push({
          y: parseInt(_val),
          name: key,
          label: "% Who Benefit:",
        });
        this.section3HeightChart = this.section3HeightChart + 50;
      }
    }
  
    this.symptomBenefitChartConfig.chart.width= this.width ;
    this.symptomBenefitChartConfig.chart.height= this.section3HeightChart;
    this.symptomBenefitChartConfig.xAxis.categories = _labels;
    this.symptomBenefitChartConfig.series[0].data = _data;
  }

  private _configureSymptomAdverseChart() {
    let _data = [];
    let _labels = [];
    const symptomsList = Object.entries(this.treatment.adverseSymptoms);
    
   
    if (symptomsList.length === 0) {
      this.nographdata = true;
      return;
    }
    for (const [key, value] of symptomsList) {
      if(key.toLowerCase().indexOf('other') === -1) {
        let _val = Number(value).toFixed(0)  
        _labels.push(_val + " %");
        _data.push({
          y: parseInt(_val),
          name: key,

          label: "% With Adverse:",
        });
        this.section4HeightChart = this.section4HeightChart + 50;
      }
    }


    this.adverseSymptomBenefitChartConfig.chart.height= this.section4HeightChart;
   
    this.adverseSymptomBenefitChartConfig.xAxis.categories = _labels;
    this.adverseSymptomBenefitChartConfig.series[0].data = _data;

    this.adverseSymptomBenefitChartConfig.chart.width= this.width ;
    this.wrapperStyle =  this.section4HeightChart  +  this.section3HeightChart + 500  + 500;
    if(this.showWarning) {
      this.wrapperStyle =  this.wrapperStyle + 100;
    }
  }

  formatTreatmentName(name) {
    if (name.length > 50) {
      let truncated: string = name.substring(0, 50).trim() + '...';
      return truncated;
    }

    return name;
  }

}
