import { NgModule } from "@angular/core";
import { RouterModule, Routes } from "@angular/router";
import { TabsPage } from "./tabs-page";
import { SchedulePage } from "../schedule/schedule";

const routes: Routes = [
  {
    path: "tabs",
    component: TabsPage,
    
    children: [
      {
        path: "speakers",
        children: [
          {
            path: "",
            loadChildren: () =>
              import("../speaker-list/speaker-list.module").then(
                (m) => m.SpeakerListModule
              ),
          },
          {
            path: "session/:sessionId",
            loadChildren: () =>
              import("../session-detail/session-detail.module").then(
                (m) => m.SessionDetailModule
              ),
          },
          {
            path: "speaker-details/:speakerId",
            loadChildren: () =>
              import("../speaker-detail/speaker-detail.module").then(
                (m) => m.SpeakerDetailModule
              ),
          },
        ],
      },
      {
        path: "schedule",
        children: [
          {
            path: "",
            component: SchedulePage,
          },
          {
            path: "session/:sessionId",
            loadChildren: () =>
              import("../session-detail/session-detail.module").then(
                (m) => m.SessionDetailModule
              ),
          },
        ],
      },
      {
        path: "about",
        children: [
          {
            path: "",
            loadChildren: () =>
              import("../about/about.module").then((m) => m.AboutModule),
          },
        ],
      },
      {
        path: "donate",
        children: [
          {
            path: "",
            loadChildren: () =>
              import("../donate/donate.module").then((m) => m.DonateModule),
          },
        ],
      },
      {
        path: "terms",
        children: [
          {
            path: "",
            loadChildren: () =>
              import("../terms/terms.module").then((m) => m.TermsModule),
          },
        ],
      },
      {
        path: "guide",
        children: [
          {
            path: "",
            loadChildren: () =>
              import("../guidelines/guidelines.module").then(
                (m) => m.GuideModule
              ),
          },
        ],
      },
      {
        path: "symptoms",
        children: [
          {
            path: "",
            loadChildren: () =>
              import("../symptom/symptom.module").then((m) => m.SymptomModule),
          },
          {
            path: "symptom/:**",
            loadChildren: () =>
              import("../symptom-detail/symptom-detail.module").then(
                (m) => m.SymptomDetailPageModule
              ),
          },
          {
            path: "symptom",
            loadChildren: () =>
              import("../symptom-detail/symptom-detail.module").then(
                (m) => m.SymptomDetailPageModule
              ),
          },
        ],
      },
      {
        path: '',
        redirectTo: "/tabs/speakers",
        pathMatch: "full",
      },
    ],
  },
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule],
})
export class TabsPageRoutingModule {}
