import { ISymptom } from './../../providers/treatments.model';
import { Component, ViewChild, OnInit } from '@angular/core';
import { Config, IonList, NavController } from '@ionic/angular';
import { ConferenceData } from '../../providers/conference-data';
import { FirestoreService } from '../../providers/firestore.service';
import { Location } from '@angular/common';
@Component({
  selector: 'page-symptom',
  templateUrl: 'symptom.html',
  styleUrls: ['./symptom.scss'],
})
export class SymptomPage implements OnInit {
  segment = 'all';
  ios: boolean;
  excludeTracks: any = [];
  symptoms: ISymptom[] = [];
  isLoading: boolean;
  isChartReady: boolean;
  showWarningGuide:boolean;
  showWarningTerms:boolean;
  data: any[];
  @ViewChild('symptomList', { static: true }) symptomList: IonList;

  constructor(public confData: ConferenceData,
    public config: Config,
    public nav: NavController,
    public location: Location,
    private api: FirestoreService) { }

  ngOnInit() {

    this.isLoading = true;
    this.data = [];
    this.loadSymptoms();
    this.ios = this.config.get('mode') === 'ios';
    this.api.getSymptomtState().then((state)=> {
    
      this.showWarningTerms = (state === null || state.warning_terms === null) ? true : false;
      this.showWarningGuide = (state === null || state.warning_guide === null) ? true : false;
     
      
    })
  }

  loadSymptoms() {
    this.api.loadSymtomps().then((resp: ISymptom[]) => {
      this.isLoading = false;
      this.symptoms = resp;
    });
  }

  onSymptomClick(symptom: any) {
 

    this.location.replaceState('/app/tabs/symptoms/symptom/');

    //let param = symptom.name.replace(' ', '').replace('/', '').replace('(', '').replace(')', '')
    let param = symptom.name.replace(' ', '-s-').replace('/', '-p-').replace('(', '-f-').replace(')', '-b-')
    let test = encodeURI(symptom.name);
    var navigationOptions = {
      queryParams: { param: symptom.name },
      replaceUrl: true, // optional,
      state: {symptom}
    };

    this.nav.navigateForward(`/app/tabs/symptoms/symptom/`, navigationOptions);
  }

  closeWarningTerms() {
    this.showWarningTerms = false;
    this.api.closeWarningSymptom('terms');
  }

  closeWarningGuide() {
    this.showWarningGuide = false;
    this.api.closeWarningSymptom('guide');
  }

}
