    async getTreatment(treatmentName: string): Promise<ITreatment> {
        return new Promise(async (resolve, reject) => {
            let _treatments = await this.loadTreatments();
            let _treatment: ITreatment = _treatments.find((treatment) => {
                return treatment.name === treatmentName;
            })
            resolve(_treatment)
        });
    }

    async getTreatmentsByCategory(category: string): Promise<ITreatment[]> {
        return new Promise(async (resolve, reject) => {
            try {

                let _treatments: ITreatment[] = await this.loadTreatments();

                if (category.toLowerCase() === 'all') {
                    resolve(_treatments);
                }
                else {
                    try {
                        let _results: ITreatment[] = _treatments.filter((resp: any) => {
                            return resp.category.name.toLowerCase().indexOf(category.toLowerCase()) !== -1;
                        })
                        if(category === 'meds') {
                           _results =  _results.sort((a,b)=> {
                            var orderA = a.category.order;
                            var orderB = b.category.order;
                            return (orderA< orderB) ? -1 : (orderA> orderB) ? 1 : 0;
                            })
                        }
                       
                        resolve(_results);
                    }
                    catch(error) {
                        throw new Error('something went wrong in Firestore Service: GetTreatmentByCategory')
                    }
                    

                    
                }
            } catch (error) {
                reject('Unable to get treatments by category');
                throw new Error("Error getting treatmentsByCategory:");
            };
        });
    }

    async getTreatmentsByCategoryGrouping(category: string): Promise<any[]> {
        return new Promise(async (resolve, reject) => {
            try {
                let _categories: any = new Map();
             
                let _treatments: ITreatment[] = await this.loadTreatments();
                let _filteredTreatments: ITreatment[] = _treatments.filter((resp: any) => {
                    if(!resp || !resp.category) {
                        return false;
                    }
                    else {
                        return resp.category.name.toLowerCase().indexOf(category.toLowerCase()) !== -1;
                    }
                    
                })

                _filteredTreatments.forEach((treatment: ITreatment)=> {
                    const _key = treatment.category.subCategory;
                    const _collection  = _categories.get(_key);
                    if(!_collection) {
                        _categories.set(_key, [treatment])
                    }
                    else {
                        _collection.push(treatment)
                    }
                })
                let _result = [..._categories].map((item)=> {
                    return {
                        'category': item[0],
                        'order': this.getCategoryOrder(item[0]),
                        'treatments': item[1]
                    }
                })
                if(category === 'meds') {
                    _result =  _result.sort((a,b)=> {
                     var orderA = a.order;
                     var orderB = b.order;
                     return (orderA< orderB) ? -1 : (orderA> orderB) ? 1 : 0;
                     })
                 }
                resolve(_result);
            } catch (error) {
                reject('Unable to get treatments by category');
                throw new Error("Error getting treatmentsByCategory:");
            };
        });
    }

