import { Component, ViewChild, ElementRef, AfterViewInit } from "@angular/core";
import { Location } from "@angular/common";

//import { PopoverController, NavParams } from '@ionic/angular';
//import { PopoverPage } from '../about-popover/about-popover';
// import Chart from 'chart.js/auto';
import { ActivatedRoute, Router } from "@angular/router";
import { FirestoreService } from "../../providers/firestore.service";
import * as Highcharts from 'highcharts';
//import { isNgTemplate } from '@angular/compiler';
import { Chart } from 'highcharts';

import { NavController, Config, IonList, ModalController, IonRouterOutlet, ToastController } from "@ionic/angular";
import { text } from 'dom7';
import { SymptomInfoComponent } from 'src/app/components/symptom-info/symptom-info.component';
import { IsDefined } from 'src/app/utils/helpers';
import { ISymptom } from 'src/app/providers/treatments.model';
import { SymptomFilterPage } from '../symptom-filter/symptom-filter';
import { filter } from 'minimatch';




@Component({
  selector: "page-symptom-detail",
  templateUrl: "symptom-detail.html",
  styleUrls: ["./symptom-detail.scss"],
})
export class SymptomDetailPage {


  Highcharts: typeof Highcharts = Highcharts;
  options: any;
  @ViewChild("wrapper", { read: ElementRef }) private wrapper: ElementRef;
  @ViewChild("treatmentList", { static: true }) scheduleList: IonList;
 
  symptomName: "";
  data: any[];
  symptoms: any[];
  leetest: any[] = [];
  showChart: boolean = false;
  docId: string;
  noOfData: number = 3;
  treatments: any[] = [];
  treatmentsFull: any = [];
  segmentFilter: any = "net";
  Isgraph: boolean = true;
  paramsValue: any;
  noDataFound: boolean = false;
  labels: any[] = [];
  sortedTreatments: any[];
  loading: boolean = false;
  isNetBenefitEnabled: boolean;
  showWarning: boolean = false;
  warningMsg: string = '';
  height: number;
  width: number;
  defaultHref: any = `/app/tabs/symptoms`;
  warningUrl: string = '';
  filterLabel: any;
  segment: string = "3";
  az: any[];
  fontSize: string = '1.5rem';

  constructor(
    private route: ActivatedRoute,
    private router: Router,
    public config: Config,
    public nav: NavController,
    public location: Location,
    private api: FirestoreService,
    public routerOutlet: IonRouterOutlet,
    public modal: ModalController,
    private toast: ToastController
  ) {
    this.route.queryParams.subscribe((_p) => {
      this.data = [];
      this.loading = true;
      const navParams = this.router.getCurrentNavigation().extras.state;
      this.paramsValue = navParams;
      this.defaultHref = `/app/tabs/symptoms`;
      //this.loadFilterLabel();
      this.isNetBenefitEnabled = true;
      this.segment = "3";
      if (navParams && navParams.symptom.treatments) {
        this.symptoms = navParams.symptom.treatments;
        this.symptomName = navParams.symptom.name;
        this.loading = false;
        if (this.symptomName.toLocaleLowerCase().indexOf('expressive language') !== -1) {
          this.showWarning = true;
          this.warningMsg = 'Only Therapies were ranked for this category, if you want to see ranked meds/supplements/diets look at Language/Communication';
          this.warningUrl = 'Language/Communication';
        }
        if (this.symptomName.toLocaleLowerCase().indexOf('language/') !== -1) {
          this.showWarning = true;
          this.warningMsg = 'Only Meds, Supplements and Diets were ranked for Language and communication, if you want to see ranked therapies, look at Expressive or Receptive Language';

          this.warningUrl = 'Expressive language (ability to say words)';
        }

      }
      else {
        this._loadTreatment();
      }
    });
  }

  ionViewDidEnter() {
    this.height = this.wrapper.nativeElement.offsetHeight;
    this.width = this.wrapper.nativeElement.offsetWidth;

    if (!this.loading) {
      this.sortData();
      this.updateChart();
    }

  }

  async loadFilterLabel() {
    let _filter = await this.api.getSymptomFilter();
  
    this.filterLabel = (!_filter) ? 'Symptom Score' :  _filter.category[0];
    this.isNetBenefitEnabled = (this.filterLabel.toLowerCase() === 'symptom score') ? true  : false; 
  }
  loadChart() {
    this.showChart = true

    this.options = {
      chart: {
        type: 'column',
        width: this.width

      },
      legend: {
        itemStyle: {
     
            fontSize: '16px'
        }
    },
      xAxis: {
        categories: this.labels,
        title: 'test',
      },
      yAxis: {
        name: '',
        text: '',
        title: '',
        labels: {
          enabled: false
        }
      },
      credits: {
        enabled: false
      },
      plotOptions: {
        animation: true,
        series: {
          borderRadius: 10,
          dataLabels: {
            borderRadius: 10,
            enabled: true,
            align: 'center',
            // color: '#FFFFFF',
            fontSize: this.fontSize,
         
            format: '{y}%',
            y: -10,
            style: {
              fontSize: this.fontSize
            }
          },
          pointPadding: 0.1,
          groupPadding: 0
        }
      },
      
      highOptions: {
        series: {

          dataLabels: {
            enabled: true,
       
            format: '{y} %',
            align: 'right',
            color: '#FFFFFF',
            x: -10
          },
          pointPadding: 0.1,
          groupPadding: 0,
        }
      },
      title: {
        text: undefined
      },
      series: [{
        color: "#2e35a8",
        name:  '% Improved',
        fontSize: '16px',
        legend: 'legendtest',
        data: this.data
      }]
    };
  }
  sort() {
    const { treatments, name, Other, other, ...newResponse } = this.symptoms as any;

   
    let _symptoms: any[] = Object.entries(newResponse);

     let _symptoms1 =  _symptoms.sort((a, b) => {
   
  
      var textA = a[0].toUpperCase();
      var textB = b[0].toUpperCase();
      return (textA < textB) ? -1 : (textA > textB) ? 1 : 0;
     
    })

    this.az = _symptoms1;
    this.loading = false;
  }
  sortData() {

    const { treatments, name, Other, other, ...newResponse } = this.symptoms as any;


    let _symptoms: any[] = Object.entries(newResponse);


    let _symptoms1 = _symptoms.sort((a, b) => {
      let _netBenefit = 0;
      let _netBenefitA = 0;
      let _netBenefitB = 0;
      if(this.isNetBenefitEnabled) {
        _netBenefitA = a[1].symptomBenefit;
        _netBenefitB = b[1].symptomBenefit;
  
      }
      else {
        _netBenefitA = a[1].benefit  - a[1].adverse;
        _netBenefitB = b[1].benefit  * b[1].adverse;
      }
    
      if (_netBenefitA < _netBenefitB) {
        return -1;
      }
      else if (_netBenefitA > _netBenefitB) {
        return 1;
      }

    })
    this.leetest = _symptoms1.reverse();

  }

  updateChart() {
    let tempList: any = [];
    let i = 0;
    this.data = [];
    this.labels = [];
    this.leetest.forEach((treatment) => {
      if (treatment && treatment[1].benefit) {
        const benifit: number = treatment[1].benefit > 0 ? treatment[1].benefit : 0;
        const adverse: number = treatment[1].adverse > 0 ? treatment[1].adverse : 0;
        if (i < this.noOfData) {
          this.labels.push(treatment[0]);
          let _netBenefit = 0;
          if(this.isNetBenefitEnabled) {
           _netBenefit = treatment[1].symptomBenefit;
          }
          else {
            _netBenefit = benifit - adverse;
          }
          

          let _val = Number(_netBenefit).toFixed(0)
          tempList.push(parseFloat(_val));

        }
        i++
      }
    })
    if (this.noOfData > tempList.length) {
      this.noOfData = tempList.length;
    }
    this.data = tempList.slice(0, this.noOfData);
    if (this.data && this.data.length > 0) {
      setTimeout(() => {
        this.loadChart();
        this.showChart = true;
        this.noDataFound = false;
      }, 10);
    } else {
      this.noDataFound = true;
    }

  }


  async onChnageTopList(event: any) {
    if (event) {
      this.noOfData = event.target.value;
      this.fontSize = (this.noOfData === 3) ? '1.8rem' : '1.0rem';
      this.loading = true;
      await this._loadTreatment();

      await this.updateChart();
      // if(this.filterLabel.toLowerCase() === 'a-z') {
      //   this.sort()
      // };
    }
  }


  onTreatmentClick(treatment: any) {

    this.api.getTreatment(treatment).then((res) => {
      
      //this.location.replaceState("/app/tabs/schedule/session/");
      let param = res.name
        .replaceAll(' ', '-s-')
        .replaceAll('/', "-f-")
        .replaceAll('(', "-sf-")
        .replaceAll("'", '-c-')
        .replaceAll('|', '-p-')
        .replaceAll(')', "-sb-");
     
      this.nav.navigateForward(`/app/tabs/schedule/session/${param}`, {
        state: {
          treatment: res,
          from: this.router.routerState.snapshot.url
        }
      });
    })

  }

  async showInfo(section: string) {
    const modal = await this.modal.create({
      component: SymptomInfoComponent,
      swipeToClose: true,
      presentingElement: this.routerOutlet.nativeEl,
      componentProps: { section: this.symptomName },
    });
    await modal.present();
  }

  segmentChanged(event: any) {
    if (event) {
      if (event.target.value == "graph") {
        this.Isgraph = true;
        this.updateChart();
      } else {
        this.Isgraph = false;
      }
    }
  }

  
  private async _loadTreatment() {


    let _urlPaths = this.router.routerState.snapshot.url.split('?param=');
    let _symptomName = _urlPaths[_urlPaths.length - 1];
    let _decode = decodeURI(_symptomName)

    _decode = _decode.replace('%2F', '/');

    let _symptom: any = await this.api.loadSymptom(_decode)
  
    this.symptoms = _symptom[0].treatments;
    this.symptomName = _symptom[0].name;

    if (this.symptomName.toLocaleLowerCase().indexOf('expressive language') !== -1) {
      this.showWarning = true;
      this.warningMsg = 'Only Therapies were ranked for this category, if you want to see ranked meds/supplements/diets look at Language/Communication';
      this.warningUrl = 'Language/Communication';
    }
    if (this.symptomName.toLocaleLowerCase().indexOf('language/') !== -1) {
      this.showWarning = true;
      this.warningMsg = 'Only Meds, Supplements and Diets were ranked for Language and communication, if you want to see ranked therapies, look at Expressive or Receptive Language';

      this.warningUrl = 'Expressive language (ability to say words)';
    }

    let _filter:string = await  this.api.getSymptomFilter();
    this.sort();
    // if(_filter !== null || _filter.toLocaleLowerCase() === 'a-z') {
    //   this.sort();
    // }
    // else {
    //   this.sortData();
    // }
 
    this.updateChart();
    this.loading = false;




  }

  onNavigateWarning() {

    //this.location.replaceState('/app/tabs/symptoms/symptom/');
    //let param = symptom.name.replace(' ', '').replace('/', '').replace('(', '').replace(')', '')

    var navigationOptions = {
      queryParams: { param: this.warningUrl },
      replaceUrl: true, // optional,

    };

    this.nav.navigateForward(`/app/tabs/symptoms/symptom/`, navigationOptions);
  }

  onSegmentChange(val:any) {
    this.segmentFilter = (val === 'net') ? 'overall' : 'net';
  }

  // TODO REPLACE WITH TREATMENT CATEGORIES ON NEXT RELEASE
  async presentFilter() {


    this.showChart = false;
    this.loading = true;

    const modal = await this.modal.create({
      component: SymptomFilterPage,
      swipeToClose: true,
      presentingElement: this.routerOutlet.nativeEl,
      componentProps: { excludedTracks: []},
    });
    await modal.present();

    const { data } = await modal.onWillDismiss();
  
  
    this.isNetBenefitEnabled = (data[0].toLocaleLowerCase() !== 'a-z')  ? true : false;
    this.filterLabel = data[0];

    // this.data = []
    // this.labels = [];
    // this.options.highOptions.series.data = [];
  
    // setTimeout(()=> {
      this.loading = false;
      this.showChart = true;
      if(this.filterLabel.toLowerCase() === 'a-z') {
        this.sort();
      }
      else {
        this.sortData();
      }
      // this._loadTreatment();
  
    // },2000);
   

  }

  public formatTreatment(val) {
   
    return Math.round(val);
  }

}
