import { Component, ViewChild, OnInit } from "@angular/core";
import { Router, NavigationExtras } from "@angular/router";
import {
  AlertController,
  IonList,
  IonRouterOutlet,
  LoadingController,
  ModalController,
  ToastController,
  Config,
  NavController,
} from "@ionic/angular";

import { ScheduleFilterPage } from "../schedule-filter/schedule-filter";
import { ConferenceData } from "../../providers/conference-data";
import { UserData } from "../../providers/user-data";
import { NavigationOptions } from "swiper/types";
import { Location } from "@angular/common";
import { ITreatment } from "../../providers/treatments.model";
import { FirestoreService } from "../../providers/firestore.service";
import { filter } from 'dom7';

@Component({
  selector: "page-schedule",
  templateUrl: "schedule.html",
  styleUrls: ["./schedule.scss"],
})
export class SchedulePage implements OnInit {
  // Gets a reference to the list element
  @ViewChild("treatmentList", { static: true }) scheduleList: IonList;

  ios: boolean;
  
  segment:string;
  showWarningTerms: boolean;
  showWarningGuide: boolean;
  excludeTracks: any = [];
  treatments: ITreatment[] = [];
  categories: any = [];
  isLoading: boolean;
  isChartReady: boolean;
  data: any[];
  filterOption: string = 'category';
  filteredTreatments: ITreatment[] = [];
  guidelineURL: string = "/app/tabs/guide/";
  termsURL: string = "/app/tabs/terms";

  constructor(
    public alertCtrl: AlertController,
    public confData: ConferenceData,
    public loadingCtrl: LoadingController,
    public modalCtrl: ModalController,
    public router: Router,
    public routerOutlet: IonRouterOutlet,
    public toastCtrl: ToastController,
    public config: Config,
    public nav: NavController,
    public location: Location,
    private api: FirestoreService
  ) { }

  async ngOnInit() {
    this.isLoading = true;
    this.data = [];
    //this.initload()
  
    this.ios = this.config.get("mode") === "ios";
    this.api.getTreatmentState('treatmentlist').then((state)=> {
      this.segment = (state === null || state.segment === null) ? 'meds' : state.segment;
      this.showWarningTerms = (state === null || state.warning_terms === null) ? true : false;
      this.showWarningGuide = (state === null || state.warning_guide === null) ? true : false;
      this.filterOption = (state === null || state.filter === null) ? 'category': state.filter;
      this.loadTreatments();
      
    })
  }

  async initload() {
  
    this.loadTreatmentsByCategoryGrouping()

  }

  filterTreatmentSegment() {

    this.api
      .getTreatmentsByCategory(this.segment.toLocaleLowerCase())
      .then(async (treatments) => {
        let _filter = await this.api.getTreatmentFilter();
        if (_filter === null || _filter.toLowerCase() !== 'category') {
          this.sort(treatments)
        }
        else {
          this.treatments = treatments;
        }
      });
  }

  filterTreatmentSegmentGroup() {
    this.api.setTreatmentTabState(this.segment.toLowerCase());
    this.isLoading = true;
    
    if (this.filterOption.toLowerCase() === 'category') { 
      
      this.api
        .getTreatmentsByCategoryGrouping(this.segment.toLocaleLowerCase())
        .then(async (treatments) => {
          this.categories = treatments;
          this.sortByGroup()
 
        });
      }
      else {
        this.loadTreatments()
      }
  }

  sort(treatments: any[]) {
  
    this.treatments = treatments.sort((a, b) => {


      var textA = a.name.toUpperCase();
      var textB = b.name.toUpperCase();
      return (textA < textB) ? -1 : (textA > textB) ? 1 : 0;

    })
    this.isLoading = false;
  }

  sortWithoutGrouping() {
    if(this.filterOption.toLowerCase() === 'a-z') {
      this.categories = this.categories.sort((a, b) => {


        var textA = a.name.toUpperCase();
        var textB = b.name.toUpperCase();
        return (textA < textB) ? -1 : (textA > textB) ? 1 : 0;
  
      })
    }
    else {

      let _treatments = this.categories.map((item) => {
        return item.treatments[0];
      });

      this.treatments = _treatments.sort((a, b) => {

        let aValAdverse = (a['overallAdverse'].value >= 0) ? a['overallAdverse'].value : 0;
        let bValAdverse = (b['overallAdverse'].value >= 0) ? b['overallAdverse'].value : 0;
        let aVal = Number(a['overallBenefit'].value - aValAdverse);
        let bVal = Number(b['overallBenefit'].value - bValAdverse);
        if (aVal == NaN) {
          aVal = 0;
        }
        if (bVal == NaN) {
          bVal = 0;
        }

        if (aVal > bVal) {
          return -1;
        }
        else {
          return 1
        }
      })
    }
    
    this.isLoading = false;
  }

  sortByGroup() {
    if(this.segment === 'diet') {
      this.sortWithoutGrouping()
      return;
    }
    else {
   
    this.categories.forEach((item) => {
      item.treatments = item.treatments.sort((a, b) => {

        let aValAdverse = (a['overallAdverse'].value >= 0) ? a['overallAdverse'].value : 0;
        let bValAdverse = (b['overallAdverse'].value >= 0) ? b['overallAdverse'].value : 0;
        let aVal = Number(a['overallBenefit'].value - aValAdverse);
        let bVal = Number(b['overallBenefit'].value - bValAdverse);
        if (aVal == NaN) {
          aVal = 0;
        }
        if (bVal == NaN) {
          bVal = 0;
        }

        if (aVal > bVal) {
          return -1;
        }
        else {
          return 1
        }
      })
    })
  }

    this.isLoading = false;
  }

  filterCategoryName(name) {
    if (name.toLowerCase() == 'allery') {
      name = name.replace('Allery', 'allergy');
    }

    if (name.toLowerCase() == 'chelation') {
      name = name.replace('Chelation Therapies', 'Chelation/Detoxification');
    }
    name = name.replace('(s)', 's')

    if (name.indexOf('meds') == -1) {

      return name;
    }
    else {
      name = name.replace('meds', ' medications ');
      return name;
    }
  }
  async loadTreatments() {
    //this.filterOption = await this.api.getTreatmentFilter();
    this.filterOption = this.filterOption.toLowerCase();
    if (this.filterOption !== null && this.filterOption.toLowerCase() !== 'category') {
      await this.api.getTreatmentsByCategory(this.segment.toLowerCase()).then(async (resp: ITreatment[]) => {



        let _treat = resp;
        if(this.segment === 'diet') {
          this.treatments = _treat;
          this.sortByGroup()
        }
        else {
          this.sort(_treat);
        }
       
      });
    }
    else {
      this.loadTreatmentsByCategoryGrouping()
    }
  }

  async loadTreatmentsByCategoryGrouping() {
  
    await this.api.getTreatmentsByCategoryGrouping(this.segment.toLocaleLowerCase()).then(async (resp: any[]) => {

      this.categories = resp;
      this.sortByGroup();

    }).catch((err) => {
      throw new Error('unable to load treatments by category grouping')
    })

  }


  onTreatmentClick(treatment: any) {
    // TEMP HACK - next release we should add NGXS!
    this.location.replaceState("/app/tabs/schedule/session/");
    let param = treatment.name
      .replace(" ", "-s-")
      .replace("/", "-f-")
      .replace("(", "-sf-")
      .replace(",", "-c-")
      .replace("|", "-p-")
      .replace(")", "-sb-");

    var navigationOptions = {
      queryParams: { param: treatment.name },
      replaceUrl: true, // optional,
      state: { 'treatment': treatment, 'from': this.router.routerState.snapshot.url }
    };
    this.nav.navigateForward(`/app/tabs/schedule/session/`, navigationOptions);
  }

  // TODO REPLACE WITH TREATMENT CATEGORIES ON NEXT RELEASE
  async presentFilter() {

    const modal = await this.modalCtrl.create({
      component: ScheduleFilterPage,
      swipeToClose: true,
      presentingElement: this.routerOutlet.nativeEl,
      componentProps: { excludedTracks: [] },
    });
    await modal.present();

    const { data } = await modal.onWillDismiss();

    this.filterOption = data[0].toLocaleLowerCase();

    if (data[0].toLocaleLowerCase() === 'category') {
      this.loadTreatmentsByCategoryGrouping()
    }
    else {

      await this.loadTreatments();

    }

  }

  getNetBenefit(a) {
    try {
      let aValAdverse = (a['overallAdverse'].value >= 0) ? a['overallAdverse'].value : 0;
      let aVal = Number(a['overallBenefit'].value - aValAdverse);
      if (aVal == NaN) {
        aVal = 0;
      }
      return aVal
    }
    catch(e) {
      throw new Error('something went wrong getting Net Benefit');
    }
    

  }
  closeWarningTerms() {
    this.showWarningTerms = false;
    this.api.closeWarning('terms');
  }

  closeWarningGuide() {
    this.showWarningGuide = false;
    this.api.closeWarning('guide');
  }

  async onFilterChange($event) {
    let _filter = $event.detail.value.toLowerCase();
    this.filterOption = _filter;
    this.api.setTreatmentFilter(_filter);

    if(_filter === 'a-z') {
      this.treatments = await this.api.getTreatmentsByCategory(this.segment.toLowerCase());
      this.sort(this.treatments)
    
    }
    else{
      this.loadTreatments();
    }
   
  }
}
